// The divisors of 360 = 2^3 * 3^2 * 5, one independent choice per row.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(127,201);
for (int i = 0; i < 4; ++i) dot((60+32*i,0), black+3pt);
for (int i = 0; i < 3; ++i) dot((60+32*i,60), black+3pt);
for (int i = 0; i < 2; ++i) dot((60+32*i,120), black+3pt);
label("$2$",(30,0),E);
label("$3$",(30,60),E);
label("$5$",(30,120),E);
label("$4 \cdot 3 \cdot 2 = 24$",(110,180),N);

// Divisors of 12 = 2^2 * 3 in a product grid: a column per power of 3, a row per
// power of 2.
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(241,181);
draw((60,30)--(220,30)--(220,150)--(60,150)--cycle);
draw((140,30)--(140,150));
draw((60,90)--(220,90));
label("$1$",(100,50));
label("$3$",(180,50));
label("$2$",(100,70));
label("$6$",(180,70));
label("$4$",(100,130));
label("$12$",(180,130));
